8.2 (b) Find MLE \(\hat{\theta}\)
Solution:
\[
\begin{aligned}
\text{(1)} \qquad &
\ell(\theta)
=
n\ln\theta
+
n\theta\ln2
-
(\theta+1)\sum_i\ln x_i
\\[1em]
\text{(2)} \qquad &
\frac{\partial\ell(\theta)}{\partial\theta}
=
0
\quad\implies\quad
{\color{red}
\boxed{
\color{black}
\hat{\theta}_{\mathrm{MLE}}
=
\frac{n}{\sum_i\ln(X_i/2)}
}}
\end{aligned}
\]

8.3 (c) Is \(\hat{\theta}\) unbiased? + MSE
Solution:
\[
\begin{array}{ll}
\text{(1) Find the distribution of }Y=\ln X
&
\\[0.5em]
\text{(1.1) Intermediate calculations:}
&
x=e^y,
\qquad
\displaystyle\frac{\partial x}{\partial y}=e^y
\\[0.5em]
&
\displaystyle
f_Y(y)
=
f_X(e^y)
\left|
\frac{\partial x}{\partial y}
\right|
\\[0.5em]
&
\displaystyle
=
\frac{\theta 2^\theta}
{e^{y(\theta+1)}}
e^y
\mathbf{1}_{[\ln2,+\infty)}(y)
\\[0.5em]
&
\displaystyle
=
\theta 2^\theta e^{-\theta y}
\mathbf{1}_{[\ln2,+\infty)}(y)
\\[0.5em]
&
\displaystyle
\implies
Y\sim\mathrm{Ga}(1,\theta)
\\[1em]
\text{(2) Distribution of }\sum_i Y_i=S:
&
{\color{red}
\boxed{
\color{black}
S\sim\mathrm{Ga}(n,\theta)
}}
\\[1em]
\text{(3) Expectation of }S^{-1}:
&
\displaystyle
\int_{2n\ln2}^{\infty}
s^{n-2}e^{-\theta s}\,ds
=
C
\times
\underbrace{
\int_{2\ln2}^{\infty}
A s^{n-2}e^{-\theta s}\,ds
}_{=\,1,\ \text{since this is a density}}
\\[0.5em]
&
\displaystyle
\text{where }
C
=
\frac{\Gamma(n-1)}{\Gamma(n)}
\frac{\theta^n}{\theta^{n-1}}
=
\frac{\theta}{n-1}
\\[1em]
\text{(4) Final expression:}
&
{\color{red}
\boxed{
\color{black}
\mathbb{E}\!\left[\hat{\theta}_{\mathrm{MLE}}\right]
=
\frac{n\theta}{n-1}
}} \implies \text{ the estimator is biased.}\\[0.5em]
\text{ (5) MSE:}& \mathrm{MSE}(\hat{\theta}) = \mathrm{Bias}^2(\hat{\theta}) + \mathrm{Var}(\hat{\theta})\\[0.5em]
\text{ (5.1) Calc second momemt:}& \mathbb{E}(S^{-2}) \underbrace{=}_{\text{if} n&gt;2} \frac{\theta^2}{(n-1)(n-2)} \implies \mathbb{E}(\hat{\theta}^2_{\mathrm{MLE}}) = \frac{n^2 \theta^2}{(n-1)(n-2)} \implies \mathrm{Var} (\hat{\theta}) = \frac{n^2 \theta^2}{(n-1)(n-2)} - \frac{n^2 \theta^2}{(n-1)^2} = \frac{n^2 \theta^2}{(n-1)^2 (n-2)} \implies \\[0.5em]
\implies \mathrm{MSE}(\hat{\theta}) = \frac{n^2 \theta^2}{(n-1)^2 (n-2)} + \frac{\theta^2}{(n-1)^2} = \frac{(n+2)(n-1)\theta^2}{(n-1)^2 (n-2)} = {\color{red}\boxed{\color{black}{\frac{n+2}{(n-1)(n-2)} \theta}}}
\end{array}
\]
